"""C4 end to end: STEP_UP -> tampered token refused -> verify -> reuse refused -> device now trusted."""
import argparse, json, urllib.error, urllib.request, uuid
from datetime import datetime, timezone


def post(url, body):
    req = urllib.request.Request(url, data=json.dumps(body).encode(),
                                 headers={"Content-Type": "application/json"})
    try:
        with urllib.request.urlopen(req, timeout=5) as r:
            return r.status, json.loads(r.read())
    except urllib.error.HTTPError as e:                  # 400/503 are expected answers here, not crashes
        return e.code, json.loads(e.read() or b"{}")


def payment(card, device, amount):
    return {"schema_version": "1.0", "transaction_id": str(uuid.uuid4()),
            "event_time": datetime.now(timezone.utc).isoformat(timespec="milliseconds"),
            "card_token": card["token"], "card_bin": "999001", "amount_minor": amount, "currency": "USD",
            "channel": "POS", "entry_mode": "chip",
            "merchant": {"id": "m_00000", "mcc": "5411", "country": "US"}, "device_id": device}


def main():
    p = argparse.ArgumentParser()
    p.add_argument("--base", default="http://localhost:8080")
    p.add_argument("--cards", default="data/cards.jsonl")
    p.add_argument("--otp", default="123456")            # local stub code from docker-compose.yml
    a = p.parse_args()
    with open(a.cards) as fh:
        card = json.loads(fh.readline())                 # first card; smoke.py uses the last one
    device, big = f"dev_e2e_{uuid.uuid4().hex[:8]}", int(float(card["avg"]) * 100 * 4)
    decide, verify = a.base + "/v1/decide", a.base + "/v1/stepup/verify"

    _, r1 = post(decide, payment(card, device, big))
    token = r1.get("challenge_token")
    if r1.get("decision") != "STEP_UP" or not token:
        raise SystemExit(f"FAIL 1: expected STEP_UP with a challenge_token, got {r1}")
    print("PASS 1 new device + 4x amount -> STEP_UP with token", r1["reasons"])

    body, sig = token.split(".")                         # change the FIRST signature character:
    tampered = body + "." + ("A" if sig[0] != "A" else "B") + sig[1:]   # always alters real bits
    checks = [("2 tampered token -> 400", post(verify, {"token": tampered, "otp": a.otp})[0] == 400),
              ("3 real token + OTP -> 200", post(verify, {"token": token, "otp": a.otp})[0] == 200),
              ("4 same token again -> 400", post(verify, {"token": token, "otp": a.otp})[0] == 400)]
    _, r2 = post(decide, payment(card, device, big))
    checks.append(("5 same device again -> no RULE_LARGE_NEW_DEVICE",
                   "RULE_LARGE_NEW_DEVICE" not in r2.get("reasons", [])))
    for name, ok in checks:
        print(("PASS " if ok else "FAIL ") + name)
    print("   second payment reply:", r2)


if __name__ == "__main__":
    main()
